{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Reduce each category's context length to max(1, floor(0.75 × baseline length)) to suppress stale interests. Existing sampling, validation, checkpoint metadata and embedded predictor consistently use this shortened length, retaining recent interactions in chronological order with matching position indices. Preserve all other settings.",
      "edits": [
        {
          "find": "MAXLEN       = int(os.environ.get(\"SASREC_MAXLEN\",    \"128\"))",
          "replace": "MAXLEN       = max(1, (3 * int(os.environ.get(\"SASREC_MAXLEN\", \"128\"))) // 4)"
        }
      ]
    }
  ],
  "change_summary": "Shorten context from 128 to 96 by default across all four category models; prediction inherits the same length through saved metadata."
}
